func findOrder(_ n: Int, _ prerequisites: [[Int]]) -> [Int] {
    var adj = [[Int]](repeating: [], count: n), indegree = [Int](repeating: 0, count: n)
    for p in prerequisites { adj[p[1]].append(p[0]); indegree[p[0]] += 1 }
    var queue = (0..<n).filter { indegree[$0] == 0 }, head = 0
    while head < queue.count {
        let c = queue[head]; head += 1
        for next in adj[c] {
            indegree[next] -= 1
            if indegree[next] == 0 { queue.append(next) }
        }
    }
    return queue.count == n ? queue : []
}
